import { Component, input, output, computed } from '@angular/core';

@Component({
  selector: 'app-user-card',
  standalone: true,
  template: `
    <article>
      <h2>{{ name() }}</h2>
      <p>{{ role() }}</p>
      <button (click)="select.emit(id())">Select</button>
